'DECLARE',
'    l_context apex_exec.t_context;',
'    l_export  apex_data_export.t_export;',
'BEGIN',
'    -- Context open',
'    l_context := apex_exec.open_query_context(',
'        p_location    => apex_exec.c_location_local_db,',
'        p_sql_query   => ''SELECT * FROM '' || apex_escape.js_literal(:P2_OBJECT_NAME)',
'    );',
'',
'    -- Export setup',
'    l_export := apex_data_export.export (',
'        p_format      => :P2_FORMAT,',
'        p_context     => l_context,',
'        p_file_name   => :P2_OBJECT_NAME',
'    );',
'',
'    apex_exec.close( l_context );',
'',
'    -- Log entry',
'    INSERT INTO app_process_logs (process_name, status)',
'    VALUES (''Extract: '' || :P2_OBJECT_NAME, ''SUCCESS'');',
'',
'    -- Ee rendu lines download ki chala important',
'    apex_data_export.download( p_export => l_export );',
'    apex_application.stop_apex_engine; ',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'Extraction Failed: #SQLERRM#'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(166153980854619837039)
,p_process_success_message=>'Extraction Successful!'
,p_internal_uid=>166153981313011837044
);
