,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Process_Uploaded_File'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_blob        BLOB;',
'    l_json_text   CLOB;',
'BEGIN',
'    -- 1. Temp storage nundi file ni pick chestunnam',
'    SELECT blob_content INTO l_blob',
'    FROM apex_application_temp_files',
'    WHERE name = :P3_FILE;',
'',
'    -- 2. BLOB ni text format (CLOB) loki marchali',
'    l_json_text := apex_util.blob_to_clob(l_blob);',
'',
'    -- 3. Boss Point 4: Log Entry (Invalid identifier error povaalante column name teedham)',
'    -- Mana table columns only (process_name, status) unte avi matrame vaadudham',
'    INSERT INTO app_process_logs (process_name, status)',
'    VALUES (''FILE_LOAD_TRIGGERED: '' || :P3_FILE, ''SUCCESS'');',
'',
'    -- Success message',
'    apex_application.g_print_success_message := ''File processed and data move initiated!'';',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>167804324270484796002
);
end;
